<?php
require __DIR__.'/config.php'; head();
$u=authRequired(); $m=$_SERVER['REQUEST_METHOD'];
if($m==='GET'){$s=db()->prepare('SELECT pa.*,p.nom,p.image,p.statut FROM panier pa JOIN produits p ON pa.produit_id=p.id WHERE pa.utilisateur_id=? ORDER BY pa.created_at DESC');$s->execute([$u['id']]);$items=$s->fetchAll();$tot=0;foreach($items as $i){$tot += (float)$i['prix']*(int)$i['quantite'];}out(['ok'=>true,'data'=>$items,'total'=>round($tot,2),'count'=>count($items)]);}
if($m==='POST'){$b=body();$pid=(int)($b['produit_id']??0);$qty=max(1,(int)($b['quantite']??1));$taille=clean($b['taille']??'M');$couleur=clean($b['couleur']??'Standard');if(!$pid)out(['ok'=>false,'err'=>'Produit invalide.'],400);$ps=db()->prepare('SELECT prix FROM produits WHERE id=? AND statut=\'actif\'');$ps->execute([$pid]);$prix=$ps->fetchColumn();if($prix===false)out(['ok'=>false,'err'=>'Produit introuvable.'],404);$sv=db()->prepare('SELECT prix_solde FROM ventes WHERE produit_id=? AND actif=1');$sv->execute([$pid]);$sol=$sv->fetchColumn();if($sol)$prix=$sol;$ex=db()->prepare('SELECT id,quantite FROM panier WHERE utilisateur_id=? AND produit_id=? AND taille=?');$ex->execute([$u['id'],$pid,$taille]);$row=$ex->fetch();if($row)db()->prepare('UPDATE panier SET quantite=? WHERE id=?')->execute([$row['quantite']+$qty,$row['id']]);else db()->prepare('INSERT INTO panier(utilisateur_id,produit_id,prix,quantite,taille,couleur)VALUES(?,?,?,?,?,?)')->execute([$u['id'],$pid,$prix,$qty,$taille,$couleur]);out(['ok'=>true,'msg'=>'Ajouté au panier.']);}
if($m==='PUT'){$b=body();$iid=(int)($b['id']??0);$qty=max(1,(int)($b['quantite']??1));db()->prepare('UPDATE panier SET quantite=? WHERE id=? AND utilisateur_id=?')->execute([$qty,$iid,$u['id']]);out(['ok'=>true,'msg'=>'Quantité mise à jour.']);}
if($m==='DELETE'){$iid=(int)($_GET['id']??0);if($iid){db()->prepare('DELETE FROM panier WHERE id=? AND utilisateur_id=?')->execute([$iid,$u['id']]);out(['ok'=>true,'msg'=>'Article supprimé.']);}db()->prepare('DELETE FROM panier WHERE utilisateur_id=?')->execute([$u['id']]);out(['ok'=>true,'msg'=>'Panier vidé.']);}
out(['ok'=>false,'err'=>'Méthode non supportée.'],405);
